void configureAuthentication(TransportCommand<?, ?> command,
                                         RepositoryConfigEntity config,
                                         CredentialsProvider credentials) {
        if (config.getAuthType() == AuthType.SSH_KEY) {
            command.setTransportConfigCallback(createSshTransportConfigCallback(config));
        } else if (credentials != null) {
            command.setCredentialsProvider(credentials);
        }
    }

    private TransportConfigCallback createSshTransportConfigCallback(RepositoryConfigEntity config) {
        String keyPath = config.getAuthSshKeyPath();
        if (keyPath == null || keyPath.isBlank()) {
            throw new RepositorySyncException(
                "SSH key path is required for SSH authentication: " + config.getName()
            );
        }

        Path resolvedKeyPath = Path.of(keyPath);
        if (!Files.exists(resolvedKeyPath)) {
            throw new RepositorySyncException(
                "SSH key file not found: " + resolvedKeyPath
            );
        }

        SshSessionFactory factory = new JschConfigSessionFactory() {
            @Override
            protected void configure(OpenSshConfig.Host host, Session session) {
                // Rely on default JSch host key verification (~/.ssh/known_hosts).
            }

            @Override
            protected JSch createDefaultJSch(FS fs) throws JSchException {
                JSch jsch = super.createDefaultJSch(fs);
                jsch.addIdentity(resolvedKeyPath.toAbsolutePath().toString());
                return jsch;
            }
        };

        return transport -> {
            if (transport instanceof SshTransport sshTransport) {
                sshTransport.setSshSessionFactory(factory);
            }
        };
    }

